// Trailhead keeps hikes sorted newest first (dates are 'YYYY-MM-DD').
function hikesReducer(state, action) {
  switch (action.type) {
    case 'added':
      state.push(action.hike);
      return state;
    case 'updated': {
      const hike = state.find((h) => h.id === action.id);
      Object.assign(hike, action.changes);
      return state;
    }
    case 'deleted':
      return state.filter((h) => h.id !== action.id);
    case 'favoriteToggled': {
      const hike = state.find((h) => h.id === action.id);
      hike.favorite = !hike.favorite;
      return state;
    }
    default:
      throw new Error('Unknown action ' + action.type);
  }
}

