const byNewest = (a, b) => b.date.localeCompare(a.date);

function hikesReducer(state, action) {
  switch (action.type) {
    case 'added':
      if (state.some((h) => h.id === action.hike.id)) return state;
      return [...state, action.hike].sort(byNewest);
    case 'updated': {
      if (!state.some((h) => h.id === action.id)) return state;
      return state
        .map((h) => (h.id === action.id ? { ...h, ...action.changes, id: h.id } : h))
        .sort(byNewest);
    }
    case 'deleted':
      return state.filter((h) => h.id !== action.id);
    case 'favoriteToggled':
      return state.map((h) => (h.id === action.id ? { ...h, favorite: !h.favorite } : h));
    default:
      return state;
  }
}

const start = [
  { id: 'a', name: 'Lake Trail', date: '2026-10-19', distanceKm: 11.2, favorite: false },
  { id: 'b', name: 'Ridge Loop', date: '2026-10-04', distanceKm: 8.4, favorite: true },
];
console.log(hikesReducer(start, { type: 'added', hike: { id: 'c', name: 'Fern Gully', date: '2026-10-10', distanceKm: 3.6, favorite: false } }).map((h) => h.id));
